    $editing = isset($schedule) && $schedule->exists;
    $selectedDay = (int) old('day_of_week', $schedule->day_of_week ?? 1);
    $isClosed = (bool) old('is_closed', $schedule->is_closed ?? false);
    $isActive = (bool) old('is_active', $schedule->is_active ?? true);
    $dayNames = [1 => __('Senin'), 2 => __('Selasa'), 3 => __('Rabu'), 4 => __('Kamis'), 5 => __('Jumat'), 6 => __('Sabtu'), 7 => __('Minggu')];
    $previewLabels = ['noHours' => __('No operating hours'), 'closed' => __('Closed'), 'active' => __('Active'), 'inactive' => __('Inactive')];
    $previewTime = $isClosed ? $previewLabels['noHours'] : old('start_time', isset($schedule) && $schedule->start_time ? substr($schedule->start_time, 0, 5) : '08:00').' - '.old('end_time', isset($schedule) && $schedule->end_time ? substr($schedule->end_time, 0, 5) : '22:00');
    $previewStatus = $isClosed ? $previewLabels['closed'] : ($isActive ? $previewLabels['active'] : $previewLabels['inactive']);
