    <script>(() => { const day = document.getElementById('day_of_week'); const start = document.getElementById('start_time'); const end = document.getElementById('end_time'); const closed = document.getElementById('is_closed'); const active = document.getElementById('is_active'); const previewDay = document.getElementById('schedule-preview-day'); const previewTime = document.getElementById('schedule-preview-time'); const previewStatus = document.getElementById('schedule-preview-status'); const dayNames = @json($dayNames); const labels = @json($previewLabels); const sync = () => { const isClosed = closed.checked; start.disabled = isClosed; end.disabled = isClosed; start.required = !isClosed; end.required = !isClosed; previewDay.textContent = dayNames[day.value]; previewTime.querySelector('span').textContent = isClosed ? labels.noHours : `${start.value || '--:--'} - ${end.value || '--:--'}`; previewStatus.className = `schedule-preview-status ${isClosed ? 'is-closed' : (active.checked ? 'is-active' : 'is-inactive')}`; previewStatus.querySelector('i').className = `fas ${isClosed ? 'fa-moon' : (active.checked ? 'fa-circle-check' : 'fa-circle-pause')}`; previewStatus.querySelector('span').textContent = isClosed ? labels.closed : (active.checked ? labels.active : labels.inactive); }; [day, start, end, closed, active].forEach(element => element?.addEventListener('change', sync)); [start, end].forEach(element => element?.addEventListener('input', sync)); sync(); })();</script>
